class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return false;
        }
        if (root.left == null && root.right == null) {
            return targetSum == root.val;
        }

        int remaining = targetSum - root.val;
        return hasPathSum(root.left, remaining) || hasPathSum(root.right, remaining);
    }
}

import java.util.*;

class Solution {
    private static final class Frame {
        final TreeNode node;
        final int remaining;

        Frame(TreeNode node, int remaining) {
            this.node = node;
            this.remaining = remaining;
        }
    }

    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return false;
        }

        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, targetSum - root.val));
        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            TreeNode node = frame.node;
            int remaining = frame.remaining;
            if (node.left == null && node.right == null && remaining == 0) {
                return true;
            }
            if (node.right != null) {
                stack.push(new Frame(node.right, remaining - node.right.val));
            }
            if (node.left != null) {
                stack.push(new Frame(node.left, remaining - node.left.val));
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    private static final class Frame {
        final TreeNode node;
        final int sum;

        Frame(TreeNode node, int sum) {
            this.node = node;
            this.sum = sum;
        }
    }

    public boolean hasPathSum(TreeNode root, int targetSum) {
        if (root == null) {
            return false;
        }

        Queue<Frame> queue = new ArrayDeque<>();
        queue.offer(new Frame(root, root.val));
        while (!queue.isEmpty()) {
            Frame frame = queue.poll();
            TreeNode node = frame.node;
            int sum = frame.sum;
            if (node.left == null && node.right == null && sum == targetSum) {
                return true;
            }
            if (node.left != null) {
                queue.offer(new Frame(node.left, sum + node.left.val));
            }
            if (node.right != null) {
                queue.offer(new Frame(node.right, sum + node.right.val));
            }
        }
        return false;
    }
}

import java.util.*;

class Solution {
    public boolean hasPathSum(TreeNode root, int targetSum) {
        List<Integer> leafSums = new ArrayList<>();
        collect(root, 0, leafSums);
        return leafSums.contains(targetSum);
    }

    private void collect(TreeNode node, int runningSum, List<Integer> leafSums) {
        if (node == null) {
            return;
        }

        int nextSum = runningSum + node.val;
        if (node.left == null && node.right == null) {
            leafSums.add(nextSum);
            return;
        }

        collect(node.left, nextSum, leafSums);
        collect(node.right, nextSum, leafSums);
    }
}
